import{_ as a,o as e,c as l,ag as r}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"导入音视频","description":"","frontmatter":{},"headers":[],"relativePath":"capture/import.md","filePath":"capture/import.md","lastUpdated":null}'),i={name:"capture/import.md"};function o(d,t,n,h,s,p){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="导入音视频" tabindex="-1">导入音视频 <a class="header-anchor" href="#导入音视频" aria-label="Permalink to &quot;导入音视频&quot;">​</a></h1><blockquote><p>把长达 3 小时的课程、会议或演讲音视频文件直接上传，让 AI 完成转写与总结</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>线上 &amp; 线下课程</strong>：将老师或讲师的整段授课录音转写为笔记，方便后期复习与检索</li><li><strong>商务会议 / 研讨会</strong>：上传录制文件，迅速产出结构化纪要，节省整理时间</li><li><strong>专题访谈 / 播客</strong>：还原对话原貌，按时间轴转写文字稿，便于后期创作与归档</li><li><strong>语音备忘录</strong>：平时录下的灵感或想法，自动转写为可搜索文本并智能汇总</li></ul><h2 id="支持的格式" tabindex="-1">支持的格式 <a class="header-anchor" href="#支持的格式" aria-label="Permalink to &quot;支持的格式&quot;">​</a></h2><p>音频：MP3、WAV、M4A 等 视频：MP4、MOV、AVI 等</p><h2 id="app-端使用" tabindex="-1">APP 端使用 <a class="header-anchor" href="#app-端使用" aria-label="Permalink to &quot;APP 端使用&quot;">​</a></h2><ol><li>打开 App，点击首页底部 + 号，选择「导入音视频」</li><li>可以从相册、本地文件中导入音视频内容</li><li>上传文件后，AI 会分析文件内容选择最佳的模板进行总结整理</li><li>完成后，AI 会生成音频对应的转写文字稿和总结笔记</li></ol><h2 id="网页端使用" tabindex="-1">网页端使用 <a class="header-anchor" href="#网页端使用" aria-label="Permalink to &quot;网页端使用&quot;">​</a></h2><ul><li>首页 → 导入音视频</li><li>知识库 → 添加 → 导入音视频</li><li>追加笔记 → 导入音视频</li></ul><h2 id="转写额度-文件时长" tabindex="-1">转写额度 &amp; 文件时长 <a class="header-anchor" href="#转写额度-文件时长" aria-label="Permalink to &quot;转写额度 &amp; 文件时长&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户类型</th><th>单次时长上限</th><th>每月转写额度</th></tr></thead><tbody><tr><td>普通用户</td><td>1 小时</td><td>3 小时</td></tr><tr><td>PRO会员</td><td>3 小时</td><td>30 小时</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">注意</p><p>转写时长额度月初重新计算不累计，下月自动更新，PRO 会员到期后自动降为普通额度。</p></div><h2 id="语音备忘录如何导入" tabindex="-1">语音备忘录如何导入？ <a class="header-anchor" href="#语音备忘录如何导入" aria-label="Permalink to &quot;语音备忘录如何导入？&quot;">​</a></h2><p>iPhone 用户可以从系统「语音备忘录」App 中导出音频文件，然后在 Get笔记中导入。</p>',15)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
